result=js(r'''(async()=>{
// Baseline renderer contracts; citywide.browser.py covers the rollout default.
const legacyCity=plots=>kit.createCityBuildings(plots,{rollout:false});
const T=await import('three'),shop=await import('./js/world/shop-slice.js'),kit=await import('./js/world/building-kit.js'),{townhouseMaterials}=await import('./js/world/building-slice-materials.js'),{createHeroIntegration,HERO_LOT_IDS}=await import('./js/world/hero-integration.js'),{stops}=await import('./js/content.js'),{routePoints,routeCurve}=await import('./js/world/layout.js'),{buildCity}=await import('./js/world/city.js');
const check=(v,m)=>{if(!v)throw Error(m)},pts=routePoints(stops.length),plots=[];buildCity(()=>{},stops,pts,routeCurve(T,pts),undefined,undefined,p=>plots.push(p));
check(JSON.stringify(shop.SHOP_LOT_IDS)===JSON.stringify(['frontage-stop-hero--255--1--9','frontage-stop-hero--255--1-0','corner-shop']),'exact three selected IDs');const selected=shop.SHOP_LOT_IDS.map(id=>plots.find(p=>p.id===id));check(selected.every(Boolean),'existing lots');const shared=townhouseMaterials(),g=shop.createShopChunk(selected,plots),maps=new Set();let triangles=0;
check(g.children.length===3,'three renderables for three shops');for(const [k,m]of g.children.entries()){check(m.material===(k===2?shared.glass:shared.architecture),'shared materials');Object.values(m.material).forEach(v=>{if(v?.isTexture)maps.add(v)});const a=m.geometry.attributes;triangles+=a.position.count/3;check(m.geometry.boundingBox&&m.geometry.boundingSphere&&m.frustumCulled&&m.castShadow===(k===0),'bounds/shadow');for(const key of ['position','normal','uv','aSurface','color'])check(a[key]?.count===a.position.count,'merge attributes');}
check(triangles<=8000&&maps.size===4,'local budget');const recipes=[];
for(const p of selected){const h=shop.createShopSlice(p,plots);recipes.push(h.userData.recipe);check(h.userData.openings.some(o=>o.type==='entry'&&o.w>=1&&o.h>=2.3),'human commercial entrance');check(h.userData.openings.some(o=>o.type==='storefront'&&o.reveal>=.4),'deep storefront');for(const m of h.children){const a=m.geometry.attributes;for(let i=0;i<a.position.count;i++){check(Math.abs(a.position.getX(i))<=p.width/2+.001&&Math.abs(a.position.getZ(i))<=p.depth/2+.001&&a.position.getY(i)>=0&&a.position.getY(i)<=p.height,'source footprint/height');check(Math.abs(new T.Vector3().fromBufferAttribute(a.normal,i).length()-1)<.0001,'normals');}for(let i=0;i<a.position.count;i+=6){const d=new T.Vector3().fromBufferAttribute(a.position,i).distanceTo(new T.Vector3().fromBufferAttribute(a.position,i+1)),uv=new T.Vector2().fromBufferAttribute(a.uv,i).distanceTo(new T.Vector2().fromBufferAttribute(a.uv,i+1));check(Math.abs(d-uv)<.0001,'metric UV');}}h.children.forEach(m=>m.geometry.dispose());}
check(recipes[0].floors===3&&recipes[2].floors===2,'height-derived floors');check(recipes[0].exposedEast===false&&recipes[1].exposedWest===false,'party wall exposure before merge');check(JSON.stringify(recipes[0])!==JSON.stringify(recipes[1]),'controlled variety');
const fp=o=>{const a=[];o.traverse(m=>{if(m.isMesh)a.push({name:m.name,cast:m.castShadow,attributes:Object.fromEntries(Object.entries(m.geometry.attributes).map(([k,v])=>[k,Array.from(v.array)])),instances:m.instanceMatrix?Array.from(m.instanceMatrix.array):null,colors:m.instanceColor?Array.from(m.instanceColor.array):null})});return JSON.stringify(a)};
check(fp(g)===fp(shop.createShopChunk(selected,plots)),'deterministic');const city=legacyCity(plots),actual=city.getObjectByName('hero-shopfronts');check(actual&&fp(actual)===fp(g),'single replacement group');const rest=new T.Group();city.children.filter(o=>o!==actual&&o.name!=='hero-zone-architecture').forEach(o=>rest.add(o.clone()));const control=legacyCity(plots.filter(p=>!shop.SHOP_LOT_IDS.includes(p.id)));control.remove(control.getObjectByName('hero-zone-architecture'));check(fp(rest)===fp(control),'all unrelated architecture unchanged');check(fp(city.getObjectByName('hero-zone-architecture'))===fp(createHeroIntegration(plots.filter(p=>HERO_LOT_IDS.includes(p.id)),plots)),'existing paving/integration unchanged');let disposed=0;actual.children.forEach(m=>m.geometry.addEventListener('dispose',()=>disposed++));city.userData.dispose();city.userData.dispose();check(disposed===3,'dispose once');let rejected=false;try{shop.createShopChunk([{...selected[0],height:12}],plots)}catch(e){rejected=e instanceof TypeError}check(rejected,'descriptor guard');return {pass:true,ids:shop.SHOP_LOT_IDS,renderables:3,triangles,materials:2,maps:4,recipes};})()''')
